\label{conj:main}
Fix $\varepsilon>0$. Let $f:\mathbb{N}\to\mathbb{U}$ be multiplicative,
and suppose that $|\alpha-a/q|\leqslant1/(qx)$, where
$(a,q)=1$ and $1\leqslant q\leqslant x/(\log x)^{2+\varepsilon}$.
Then
\begin{equation}\label{eq:conjecture}
 |S_f(x,\alpha)|
 \ll_\varepsilon
 \frac{x}{\log x}+\frac{x}{\sqrt q}.
\end{equation}

\label{thm:main}
Let $f:\mathbb{N}\to\mathbb{U}$ be multiplicative, and suppose that
$|\alpha-a/q|\leqslant1/(qx)$, where $(a,q)=1$ and
$1\leqslant q\leqslant Q_{\rm MV}(x)$. Then
\begin{equation}\label{eq:main-expanded}
 |S_f(x,\alpha)|
 \leqslant
 \left(\frac4{\sqrt6}+o(1)\right)\frac{x}{\sqrt q}
 +O\left(\frac{x}{\log x}\right).
\end{equation}
If $f$ is completely multiplicative, then
\begin{equation}\label{eq:complete-main}
 |S_f(x,\alpha)|
 \leqslant
 (1+o(1))\frac{x}{\sqrt q}
 +O\left(\frac{x}{\log x}\right).
\end{equation}
Both leading constants are best possible, and the
estimates are uniform in $f,a,q$, and $\alpha$.
In particular, Conjecture~\ref{conj:main} holds
for every fixed $\varepsilon>0$.

\label{lem:phase}
If $|\alpha-a/q|\leqslant 1/(qX)$ and $|f(n)|\leqslant1$, then
\begin{equation}\label{eq:phase}
 |S_f(X,\alpha)-S_f(X,a/q)|\ll \frac{X}{q}.
\end{equation}

\label{lem:conv}
There is a multiplicative function $h$ such that $f=h*F_q$, with $h(p^k)=0$ for $p\mid q$, $h(p)=0$ for $p\nmid q$, and
$h(p^k)=f(p^k)-f(p)f(p^{k-1})$ for $p\nmid q$ and $k\geqslant2$. In particular,
\begin{equation}\label{eq:h-sums}
 \sum_{d\geqslant1}\frac{|h(d)|}{d}<\infty,
 \qquad
 \sum_{d\geqslant1}\frac{|h(d)|}{d^{1-\delta}}<\infty
 \quad(0<\delta<1/2).
\end{equation}

\label{prop:reduction}
Suppose that, whenever $X$ is large, $q\leqslant8(\log X)^3$, and
$F:\mathbb{N}\to\mathbb{U}$ is multiplicative and completely multiplicative at every
prime $p\nmid q$, one has
\begin{equation}\label{eq:local-goal}
 S_F(X,\theta)\ll \frac{X}{\log X}+\frac{X}{\sqrt q}
\end{equation}
for $|\theta-b/q|\leqslant1/(qX)$ and $(b,q)=1$. Then the same estimate
holds, under the same approximation hypothesis, for every multiplicative
$f:\mathbb{N}\to\mathbb{U}$ whenever $q\leqslant(\log x)^3$.

\label{prop:large-prime}
Uniformly for $q\leqslant8L^3$ and $(a,q)=1$,
\begin{equation}\label{eq:large-prime}
 \sum_{\substack{n\leqslant x\\P^{+}(n)>x/q}}F(n)\mathrm e(an/q)\ll \frac{x}{\log x}.
\end{equation}

\label{lem:shiu-weight}
Uniformly for $0\leqslant z\leqslant1$ and $u\geqslant1$,
\begin{equation}\label{eq:shiu-total}
 \sum_{m\leqslant u}w_z(m)\ll u\rho_z(u).
\end{equation}
If $u\geqslant q^4$, then uniformly for every $b\pmod q$,
\begin{equation}\label{eq:shiu-progression}
 \sum_{\substack{m\leqslant u\\m\equiv b\pmod q}}w_z(m)
 \ll\frac uq\rho_z(u).
\end{equation}

\label{lem:ramare-mass}
With the notation above,
\begin{equation}\label{eq:ramare-mass}
 \int_0^1\sum_{j<J}
 \frac{\Delta_jM_j}{\log t_j}\rho_z(M_j)\,\mathrm{d} z
 \ll x.
\end{equation}

\label{lem:gauss-l2}
For every $v\in\mathbb{Z}$,
\begin{equation}\label{eq:gauss-l2}
 \sum_{\chi\pmod q}|G_q(v,\chi)|^2=\phi(q)^2.
\end{equation}

\label{lem:gauss-pointwise}
For every $v\in\mathbb{Z}$ and every character $\chi\pmod q$,
\begin{equation}\label{eq:gauss-pointwise}
 |G_q(v,\chi)|\leqslant\sqrt{q(v,q)}.
\end{equation}

\label{lem:gauss-l1}
Uniformly in $\chi\pmod q$ and $(a,q)=1$,
\begin{equation}\label{eq:gauss-l1}
 \sum_{v\bmod q}|G_q(av,\chi)|
 \leqslant\frac4{\sqrt6}\phi(q)\sqrt q.
\end{equation}

\label{prop:exceptional}
If $M_j\geqslant q^4$, then, uniformly for $0\leqslant z\leqslant1$ and
all $\chi\pmod q$,
\begin{equation}\label{eq:exceptional-bound}
 |B_{j,z}(\chi)|\ll
 \frac{\phi(q)}{\sqrt q}\,M_j\rho_z(M_j).
\end{equation}
Consequently the total contribution of the selected coefficient
$|B_{j,z}(\chi_{j,z})|$ in \eqref{eq:ramare-master}, over the
blocks with $M_j\geqslant q^4$, is $O(x/\sqrt q)$.

\label{lem:PLS}
Let $g\in\mathcal C(1)$ and $M\geqslant q^4$. There is a
character $\chi_0\pmod q$ such that
\begin{equation}\label{eq:PLS}
 \left(\sum_{\substack{\chi\pmod q\\\chi\ne\chi_0}}
   \left|\sum_{n\leqslant v}g(n)\chi(n)\right|^2\right)^{1/2}
 \ll v\mathfrak D(M,q)
\end{equation}
uniformly for $\sqrt M\leqslant v\leqslant M$.
If no exceptional character is needed, choose $\chi_0$ arbitrarily.

\label{prop:weighted-pls}
If $M_j\geqslant q^4$, then for each $z\in[0,1]$ there exists a character
$\chi_{j,z}\pmod q$ satisfying
\begin{equation}\label{eq:weighted-pls}
 \left(\sum_{\substack{\chi\pmod q\\\chi\ne\chi_{j,z}}}
  |B_{j,z}(\chi)|^2\right)^{1/2}
 \ll H(q)\bigl(\sqrt q\,M_j\mathfrak D(M_j,q)
     +\phi(q)M_j^{3/4}\bigr).
\end{equation}

\label{lem:short-M}
If $q\leqslant M_j<q^4$, then for every $z\in[0,1]$,
\begin{equation}\label{eq:short-M}
 \left(\sum_{\chi\pmod q}|B_{j,z}(\chi)|^2\right)^{1/2}
 \leqslant \sqrt{2\phi(q)}\,M_j.
\end{equation}

\label{prop:smooth-core}
Suppose that $q\leqslant8(\log x)^3$, $(a,q)=1$, and $F:\mathbb{N}\to\mathbb{U}$
is multiplicative and completely multiplicative at every prime
$p\nmid q$. Then
\begin{equation}\label{eq:smooth-core}
 \sum_{\substack{n\leqslant x\\P^+(n)\leqslant x/q}}
      F(n)\mathrm e(an/q)
 \ll\frac{x}{\log x}+\frac{x}{\sqrt q}.
\end{equation}

\label{prop:basic-bound}
Under the hypotheses of Theorem~\ref{thm:main}, one has
\begin{equation}\label{eq:basic-bound}
 S_f(x,\alpha)\ll\frac{x}{\log x}+\frac{x}{\sqrt q}.
\end{equation}

\label{lem:general-primary-kernel}
Uniformly in $\chi\pmod q$ and $(a,q)=1$,
\begin{equation}\label{eq:general-primary-kernel}
 \sum_{d\in\mathcal D_q}\frac{|G_q(ad,\overline\chi)|}{d}
 \leqslant\frac4{\sqrt6}\sqrt q.
\end{equation}
For each fixed $0<\rho<1/2$,
\begin{equation}\label{eq:general-primary-weighted-kernel}
 \sum_{d\in\mathcal D_q}\frac{|G_q(ad,\overline\chi)|}{d^{1-\rho}}
 \ll_\rho q^{1/2+o(1)}.
\end{equation}
If $f$ is completely multiplicative and $|f(n)|\leqslant1$, then, for
all real $t$,
\begin{equation}\label{eq:complete-primary-kernel}
 \left|\sum_{d\in\mathcal D_q}
 \frac{f(d)G_q(ad,\overline\chi)}{d^{1+it}}\right|
 \leqslant\sqrt q.
\end{equation}

\label{lem:general-level-q-sieve}
Fix $A>0$. There is a set $\mathcal E_q$ of characters modulo $q$, with
$|\mathcal E_q|\leqslant1$, such that, uniformly for
$x/L^A\leqslant Y\leqslant x$,
\begin{equation}\label{eq:general-level-q-sieve}
 \left(\sum_{\substack{\chi\bmod q\\\chi\notin\mathcal E_q}}
 |M_\chi(Y)|^2\right)^{1/2}
 \ll_A YL^{-(1-1/\sqrt2)+o(1)}.
\end{equation}

\label{lem:general-weighted-tail}
Fix $A>0$. There is a set $\mathcal E$ of characters modulo $q$, with
$|\mathcal E|=L^{o(1)}$, such that, uniformly for
$x/L^A\leqslant X\leqslant x$ and $X/L^A\leqslant Y\leqslant X$,
\begin{equation}\label{eq:general-weighted-tail}
 \frac1L\sum_{\substack{\chi\bmod q\\\chi\notin\mathcal E}}
 \left|\sum_{n\leqslant Y}f(n)\chi(n)w_X(n)\right|
 \ll_A Y\left(\frac{\log Z_A}{L}\right)^{2/3}.
\end{equation}

\label{lem:weighted-large-prime-boundary}
Let $Z$ be any fixed sufficiently large power of $qL$, with
$Z\ll L^{O(1)}$, and let $x/L^A\leqslant X\leqslant x$. Uniformly in
$(a,q)=1$,
\begin{equation}\label{eq:weighted-large-prime-boundary}
 \sum_{X/Z<p\leqslant X}f(p)\log p
     \sum_{m\leqslant X/p}f(m)\mathrm e(apm/q)
 \ll_A X+\frac{X2^{\omega(q)/2}}{\sqrt{\phi(q)}}\log(2Z).
\end{equation}

\label{prop:general-one-character}
Fix $A>0$. There is a function $\delta_A(x)\to0$ and a choice of at most one
exceptional character $\chi_0\pmod q$ such that, uniformly for $x/L^A\leqslant X\leqslant x$,
\begin{equation}\label{eq:general-one-character}
\begin{aligned}
 S_f(X,a/q)
 ={}&\frac1{\phi(q)}
 \sum_{d\in\mathcal D_q}f(d)G_q(ad,\overline{\chi_0})M_{\chi_0}(X/d)\\
 &\quad+O_A\left(\frac XL\right)
 +\delta_A(x)\frac X{\sqrt q}.
\end{aligned}
\end{equation}
If there is no exceptional character, the first term is omitted.

\label{lem:general-stability}
Fix $A>0$ and let $\chi\pmod q$. There are a real $|t|\leqslant L$
and an absolute constant $\eta_1>0$ such that, uniformly for
$1\leqslant u\leqslant L^A$ and $|\gamma|\leqslant1/(qx)$,
\begin{equation}\label{eq:general-stability}
 \sum_{n\leqslant x/u}f(n)\chi(n)\mathrm e(\gamma un)
 =\frac{\mathcal H_x(\gamma,t)}{u^{1+it}}M_\chi(x)
  +O_A\left(\frac{x}{uL^{\eta_1}}\right).
\end{equation}
Moreover,
\begin{equation}\label{eq:general-amplitude-bound}
 |\mathcal H_x(\gamma,t)M_\chi(x)|
 \leqslant\frac{\phi(q)}q x
   +O_A\left(2^{\omega(q)}+\frac{x}{L^{\eta_1}}\right).
\end{equation}
